'use strict';const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');const html=fs.readFileSync(__dirname+'/world.html','utf8'),src=html.match(/<script id="world-engine">([\s\S]*?)<\/script>/)[1],context={};context.globalThis=context;vm.runInNewContext(src,context);const E=context.WorldRules;
function key(s){return [s.player.x,s.player.y,s.collected,s.fluid,s.grip,s.stage].join(',');}function solve(level,allowPower=true){const first=E.create(level),q=[{s:first,path:[]}],seen=new Set([key(first)]);for(let i=0;i<q.length;i++){const {s,path}=q[i];if(s.won)return path;for(const a of ['up','down','left','right',...(allowPower?['power','phase']:[])]){const n=JSON.parse(JSON.stringify(s));n.history=[];if(!E.act(n,a))continue;const k=key(n);if(!seen.has(k)){seen.add(k);q.push({s:n,path:[...path,a]});}}}return null;}
for(let i=0;i<E.levels.length;i++){const path=solve(i);assert.ok(path,'solvable level '+i);const s=E.create(i);for(const a of path)E.act(s,a);assert.ok(s.won);assert.ok(s.collected);assert.equal(s.player.x,s.exit.x);assert.equal(s.player.y,s.exit.y);console.log('Level '+(i+1)+' verified solution, '+path.length+' actions: '+path.join(' '));}
assert.equal(solve(1,false),null,'phase rule required');assert.equal(solve(2,false),null,'friction rule required');let s=E.create(0),before=JSON.stringify(s.player);E.act(s,'right');assert.notEqual(JSON.stringify(s.player),before);E.act(s,'undo');assert.equal(JSON.stringify(s.player),before);for(let i=0;i<E.levels.length;i++){const s=E.create(i);for(let n=0;n<500;n++){E.act(s,['up','down','power','right','left','undo'][n%6]);assert.ok(!E.solid(s,s.player.x,s.player.y));assert.ok(s.player.x>=0&&s.player.y>=0);}}assert.ok(!/https?:\/\//.test(html));console.log('6 BFS solvability checks, mandatory rule checks, undo and 3000 deterministic legal-state transitions passed; no external dependencies.');
const gate=E.create(1);gate.fluid=true;gate.player={x:4,y:3};const gateBefore=JSON.stringify({player:gate.player,fluid:gate.fluid,moves:gate.moves});assert.equal(E.act(gate,'power'),false);assert.equal(JSON.stringify({player:gate.player,fluid:gate.fluid,moves:gate.moves}),gateBefore);assert.equal(gate.message,'inside');const wall=E.create();assert.equal(E.act(wall,'up'),false);assert.equal(wall.moves,0);for(let level=0;level<E.levels.length;level++){const a=E.create(level),b=E.create(level);for(const cmd of solve(level)){E.act(a,cmd);E.act(b,cmd);}assert.equal(JSON.stringify(a),JSON.stringify(b));const finished=JSON.stringify(a);assert.equal(E.act(a,'right'),false);assert.equal(JSON.stringify(a),finished);assert.equal(E.act(a,'undo'),true);assert.equal(a.won,false);}console.log('Gate occupancy, blocked moves, deterministic replay and victory/undo boundaries passed.');
// Level 4 needs both opening a route AND rebuilding a stopping point.
function constrained(level,permit){const q=[{s:E.create(level),n:0}],seen=new Set();for(let i=0;i<q.length;i++){const {s,n}=q[i];if(s.won)return true;for(const cmd of ['up','down','left','right','power','phase']){if(!permit(s,cmd,n))continue;const next=JSON.parse(JSON.stringify(s));next.history=[];if(!E.act(next,cmd))continue;const nn=n+(cmd==='power'?1:0),k=key(next)+','+Math.min(nn,8);if(!seen.has(k)){seen.add(k);q.push({s:next,n:nn});}}}return false;}
assert.equal(constrained(3,(s,c,n)=>c!=='power'||n<1),false,'opening alone cannot provide the exit brake');assert.equal(solve(3,false),null);assert.equal(solve(4,false),null);assert.equal(constrained(4,(s,c)=>c!=='power'||!s.grip),false,'permanent high friction cannot cross the gap');
let relay=E.create(4);relay.grip=true;relay.player={x:7,y:3};E.act(relay,'down');assert.equal(relay.stage,0,'node2 cannot precede node1');relay.player={x:2,y:3};E.act(relay,'right');assert.equal(relay.stage,1);E.act(relay,'undo');assert.equal(relay.stage,0,'undo restores relay progression');relay=E.create(4);relay.player={x:4,y:3};relay.grip=true;assert.equal(E.act(relay,'right'),false,'high friction blocks the gap');relay.grip=false;assert.equal(E.act(relay,'right'),true,'low friction crosses the gap');assert.equal(relay.player.x,8);assert.equal(relay.stage,0,'crossing nodes without high-friction docking cannot connect them');
// Old rooms and shortest solutions remain unchanged.
assert.deepEqual([0,1,2].map(i=>solve(i).length),[6,11,10]);assert.match(html,/TrialProgress\?\.complete\('world',s.level,\{moves:s.moves\}\)/);assert.match(html,/flex-wrap:wrap/);const gameScripts=[...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/g)].filter(m=>! /\bid=["']local-progress["']/.test(m[1]));assert.equal(gameScripts.length,2,'engine and UI scripts remain distinct from shared progress');for(const script of gameScripts){assert.ok(!/localStorage|sessionStorage/.test(script[2]),'game scripts delegate storage to shared progress');new vm.Script(script[2]);}
console.log('Combination necessity passed: reversible wall as brake, numbered docking order, low-friction gap, undo stage, unchanged original rooms and optional progress hook.');
// Finale integrates docking, momentum crossing and reversible sealing, with a tested optional route.
const finale=E.create(5);for(const cmd of E.levels[5].hintRoute)assert.equal(E.act(finale,cmd),true,'hint command works: '+cmd);assert.ok(finale.won);assert.equal(finale.stage,2);assert.equal(finale.fluid,false);assert.equal(constrained(5,(s,c)=>c!=='phase'),false,'liquefying is necessary');assert.equal(constrained(5,(s,c)=>c!=='power'),false,'precise docking is necessary');assert.equal(constrained(5,(s,c)=>c!=='phase'||!s.fluid),false,'opening without sealing cannot finish');const beforeSeal=E.create(5);for(const cmd of E.levels[5].hintRoute.slice(0,-1))E.act(beforeSeal,cmd);assert.equal(beforeSeal.collected,true);assert.equal(beforeSeal.player.x,beforeSeal.exit.x);assert.equal(beforeSeal.won,false);assert.equal(beforeSeal.message,'seal');E.act(beforeSeal,'phase');assert.equal(beforeSeal.won,true);E.act(beforeSeal,'undo');assert.equal(beforeSeal.won,false);assert.equal(beforeSeal.fluid,true);assert.equal(beforeSeal.stage,2);assert.deepEqual([0,1,2,3,4].map(i=>solve(i).length),[6,11,10,4,17]);assert.match(html,/E\.levels\[5\]\.hintRoute\.map/);assert.ok(!html.includes('ROUTE_ZH'));console.log('Finale: all three mechanism necessities, exact hint execution, independent switches, sealing-at-exit and full undo passed; original five shortest solutions preserved.');
