assert.match(html,/@media\(min-width:900px\) and \(min-height:560px\)/);assert.match(html,/grid-template-rows:auto auto auto minmax\(0,1fr\) auto/);assert.match(html,/object-fit:contain/);assert.match(html,/overflow-y:auto;overscroll-behavior:contain/);assert.ok(html.includes('完成记录本地保存'));assert.ok(html.includes('completion records are saved locally'));assert.ok(!html.includes('offline, no save'));console.log('Desktop containment rules and accurate local-completion copy passed (not a browser layout test).');
